async fn elevenlabs_api(api_key: &str, api_secret: &str, text: &str) -> String {
    let client = Client::new();
    let res = client
        .post("https://api.elevenlabs.io/v1/text-to-speech")
        .header("Authorization", format!("Bearer {}", api_key))
        .header("Content-Type", "application/json")
        .body(json!({
            "text": text,
            "voice": "en-US",
            "speed": 1.0,
            "pitch": 1.0,
            "volume": 1.0,
        }))
        .send()
        .await
        .unwrap();

    let audio_url = res.json::<AudioUrl>().await.unwrap().url;

    audio_url
}

async fn download_audio(url: &str) -> String {
    let client = Client::new();
    let res = client.get(url).send().await.unwrap();
    let audio_file = res.text().await.unwrap();

    audio_file
}

struct AudioUrl {
